export class NotionParser {
    /**
     * Converts Notion blocks to a clean, optimized JSON structure
     * suitable for Astro rendering.
     */
    static parseBlocks(blocks) {
        return blocks.map(block => {
            const parsed = {
                id: block.id,
                type: block.type,
                content: this.extractContent(block)
            };
            if (block.children) {
                parsed.children = this.parseBlocks(block.children);
            }
            return parsed;
        });
    }
    static extractContent(block) {
        const type = block.type;
        const data = block[type];
        switch (type) {
            case 'paragraph':
            case 'heading_1':
            case 'heading_2':
            case 'heading_3':
            case 'bulleted_list_item':
            case 'numbered_list_item':
            case 'to_do':
            case 'quote':
            case 'toggle':
                return {
                    rich_text: data.rich_text,
                    checked: data.checked // For to_do
                };
            case 'image':
            case 'video':
            case 'file':
            case 'pdf':
                return {
                    url: data.file?.url || data.external?.url,
                    caption: data.caption,
                    type: data.type // 'file' or 'external'
                };
            case 'code':
                return {
                    rich_text: data.rich_text,
                    language: data.language
                };
            case 'callout':
                return {
                    rich_text: data.rich_text,
                    icon: data.icon
                };
            case 'button':
                return {
                    rich_text: data.rich_text,
                    outline: data.outline,
                    color: data.color
                };
            case 'bookmark':
                return {
                    url: data.url,
                    caption: data.caption
                };
            case 'child_database':
                const metadata = this.parseDatabaseMetadata(data);
                return {
                    title: metadata.title,
                    original_title: data.title,
                    viewType: metadata.viewType,
                    layoutFlags: metadata.layoutFlags,
                    // If the backend has injected `database_schema` and `database_rows` (Enrichment Strategy)
                    schema: block.database_schema,
                    rows: block.database_rows ? block.database_rows.map((row) => ({
                        id: row.id,
                        icon: row.icon?.emoji || row.icon?.external?.url || row.icon?.file?.url || null,
                        cover: row.cover?.external?.url || row.cover?.file?.url || null,
                        properties: this.parseDatabaseProperties(row.properties, block.database_schema),
                        url: row.url
                    })) : []
                };
            case 'equation':
                return {
                    expression: data.expression
                };
            case 'divider':
            case 'column_list':
            case 'column':
            case 'synced_block':
                return {};
            case 'table':
                return {
                    table_width: data.table_width,
                    has_column_header: data.has_column_header,
                    has_row_header: data.has_row_header
                };
            case 'table_row':
                return {
                    cells: data.cells // This is an array of rich_text arrays
                };
            default:
                // Return raw data if not explicitly handled
                return data;
        }
    }
    static parseDatabaseMetadata(data) {
        const title = data.title || "";
        const description = data.description || ""; // Assuming description is passed in data if available
        const knownTags = ['Gallery', 'Masonry', 'Board', 'List', 'Hero', 'Calendar', 'Timeline', 'Feed', 'Kanban', 'Table'];
        const pattern = new RegExp(`\\[(${knownTags.join('|')})\\]`, 'gi');
        // Helper to extract tags
        const extract = (text) => {
            const matches = text.match(pattern);
            return matches ? matches.map(m => m.replace(/[\[\]]/g, '')) : [];
        };
        // Extract from Description first (primary source for configuration)
        let magicTags = extract(description);
        // If no tags in description, fallback to Title
        if (magicTags.length === 0) {
            magicTags = extract(title);
        }
        // Priority Logic for View Type
        let viewType = 'table';
        const hasTag = (tag) => magicTags.some(t => t.toLowerCase() === tag.toLowerCase());
        if (hasTag('Calendar'))
            viewType = 'calendar';
        else if (hasTag('Timeline'))
            viewType = 'timeline';
        else if (hasTag('Gallery'))
            viewType = 'gallery';
        else if (hasTag('Board') || hasTag('Kanban'))
            viewType = 'board';
        else if (hasTag('Feed'))
            viewType = 'feed';
        else if (hasTag('List'))
            viewType = 'list';
        // Default is table
        // Sanitize Title (Remove known Magic Tags from the title ONLY)
        // We always clean the title even if tags came from description to be safe, 
        // but typically tags in description don't affect title. 
        // The requirement is "Title Sanitization".
        const cleanTitle = title.replace(pattern, '').trim();
        return {
            title: cleanTitle,
            viewType,
            layoutFlags: magicTags
        };
    }
    static parseDatabaseProperties(properties, schema) {
        const parsed = {};
        if (!properties)
            return parsed;
        for (const [key, value] of Object.entries(properties)) {
            const prop = value;
            const type = prop.type;
            if (!type)
                continue;
            switch (type) {
                case 'title':
                case 'rich_text':
                    parsed[key] = prop[type]?.map((t) => t.plain_text).join('') || '';
                    break;
                case 'select':
                    parsed[key] = prop.select; // { name, color } or null
                    break;
                case 'multi_select':
                    parsed[key] = prop.multi_select; // Array of { name, color }
                    break;
                case 'date':
                    parsed[key] = prop.date; // { start, end, time_zone } or null
                    break;
                case 'checkbox':
                    parsed[key] = prop.checkbox;
                    break;
                case 'url':
                    parsed[key] = prop.url;
                    break;
                case 'email':
                    parsed[key] = prop.email;
                    break;
                case 'phone_number':
                    parsed[key] = prop.phone_number;
                    break;
                case 'files':
                    parsed[key] = prop.files?.map((f) => f.file?.url || f.external?.url) || [];
                    break;
                case 'people':
                    parsed[key] = prop.people?.map((p) => ({
                        id: p.id,
                        name: p.name,
                        avatar_url: p.avatar_url
                    })) || [];
                    break;
                case 'status':
                    parsed[key] = prop.status; // { name, color }
                    break;
                case 'created_time':
                    parsed[key] = prop.created_time;
                    break;
                case 'last_edited_time':
                    parsed[key] = prop.last_edited_time;
                    break;
                case 'number':
                    parsed[key] = prop.number;
                    break;
                case 'formula':
                    if (prop.formula.type === 'string')
                        parsed[key] = prop.formula.string;
                    else if (prop.formula.type === 'number')
                        parsed[key] = prop.formula.number;
                    else if (prop.formula.type === 'boolean')
                        parsed[key] = prop.formula.boolean;
                    else if (prop.formula.type === 'date')
                        parsed[key] = prop.formula.date;
                    break;
                case 'relation':
                    parsed[key] = prop.relation?.map((r) => r.id) || [];
                    break;
                case 'rollup':
                    if (prop.rollup.type === 'array') {
                        parsed[key] = prop.rollup.array;
                    }
                    else {
                        parsed[key] = prop.rollup[prop.rollup.type];
                    }
                    break;
                default:
                    parsed[key] = null;
            }
        }
        return parsed;
    }
}
